FUNCTION_BLOCK FB
VAR_INPUT
    enqueue  : BOOL;
    dequeue  : BOOL;
    reset    : BOOL;
    capacity : DINT;
END_VAR

VAR_OUTPUT
    elementCount : DINT := 0;
    status       : WORD := 16#0000;
END_VAR

VAR_IN_OUT
    item   : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR

VAR
    head        : DINT := 1;
    tail        : DINT := 1;
    prevEnqueue : BOOL := FALSE;
    prevDequeue : BOOL := FALSE;
END_VAR

// Rising edge detection
IF enqueue AND NOT prevEnqueue THEN
    IF reset THEN
        // Reset takes priority
    ELSIF elementCount < capacity THEN
        buffer[tail] := item;
        tail := (tail MOD capacity) + 1;
        elementCount := elementCount + 1;
        status := 16#0000;
    ELSE
        status := 16#8002;
    END_IF
ELSIF dequeue AND NOT prevDequeue THEN
    IF reset THEN
        // Reset takes priority
    ELSIF elementCount > 0 THEN
        item := buffer[head];
        head := (head MOD capacity) + 1;
        elementCount := elementCount - 1;
        status := 16#0000;
    ELSE
        status := 16#8001;
    END_IF
ELSIF reset THEN
    elementCount := 0;
    status := 16#0000;
ELSE
    status := 16#0000;
END_IF

prevEnqueue := enqueue;
prevDequeue := dequeue;
END_FUNCTION_BLOCK
```

